import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.ojwJKwrc.js";const _=JSON.parse('{"title":"RTLMeter","description":"","frontmatter":{},"headers":[],"relativePath":"ja/benchmarks/rtlmeter.md","filePath":"ja/benchmarks/rtlmeter.md"}'),o={name:"ja/benchmarks/rtlmeter.md"};function l(m,e,n,c,i,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="rtlmeter" tabindex="-1">RTLMeter <a class="header-anchor" href="#rtlmeter" aria-label="Permalink to &quot;RTLMeter&quot;">​</a></h1><p><a href="./?tab=rtlmeter">RTLMeter ダッシュボード</a>で、Celox・Verilator・xezim の 2-state / 4-state 比較を確認できます。対象は固定した RTLMeter の XuanTie-E902 / E906 と HummingbirdV2-E203 の <code>hello</code> です。 E203 は上流の <code>default</code> 構成（フリップフロップの <code>#1</code> 遅延を含む）を使用し、 assertion を有効にした通常の共有変数の意味論で実行します。</p><p>測定値は、同じ VM・論理 CPU 上で順番を入れ替えて実行した 3 回の中央値です。 HDL の読み込みからコンパイル、起動、実行完了までを含みます。Verilator には C++ のビルド時間も含め、毎回新しいビルド先を使います。短いプログラムの 開発時の待ち時間を比較するもので、定常実行のスループットではありません。</p><p>2-state と 4-state は別のグラフにします。Verilator 5.052 の 4-state は実験的機能で、 X/Z の事前確認に通った場合だけ測定します。xezim は Nix で安定版リリースを固定し、 通常の 4-state VM を使用します。全体を 2-state にするモードはないため、2-state は 未対応と表示します。ゼロ初期化を 2-state の代用にはしません。</p><p>成功出力・終了コード・最終クロック数と、1 クロックで止める負の対照実験を検証します。 未対応・失敗・タイムアウトは表に表示し、性能値には加えません。毎日 04:37 UTC と 手動実行で比較し、master の結果を掲載します。生ログは 30 日間保存します。</p><p>固定リビジョン、ツール設定、実行例は<a href="./../../benchmarks/rtlmeter.html">英語の測定仕様</a>を参照してください。</p>',6)])])}const h=t(o,[["render",l]]);export{_ as __pageData,h as default};
